#!/usr/bin/env python3
"""Air Jordan Sneaker Resale Market Analysis Report Generator."""

import pandas as pd
import numpy as np
import plotly.graph_objects as go
import plotly.express as px
from plotly.subplots import make_subplots
import json
import textwrap

# ── Load & prepare data ──────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Sale_Date'] = pd.to_datetime(df['Sale_Date'])
df['Year'] = df['Sale_Date'].dt.year
df['Month'] = df['Sale_Date'].dt.to_period('M')
df['Resale_to_Retail'] = df['Resale_Price_USD'] / df['Retail_Price_USD']
df['Is_Profitable'] = df['Resale_Price_USD'] > df['Retail_Price_USD']

# ── Compute KPIs ─────────────────────────────────────────────────────
avg_profit_margin = df['Profit_Margin_USD'].mean()
resale_premium_rate = df['Is_Profitable'].mean() * 100
avg_days_inventory = df['Days_in_Inventory'].mean()
avg_resale_to_retail = df['Resale_to_Retail'].mean()
top_colorway_margin = df.groupby('Colorway')['Profit_Margin_USD'].mean().max()
top_colorway_name = df.groupby('Colorway')['Profit_Margin_USD'].mean().idxmax()

total_txns = len(df)
date_min = df['Sale_Date'].min().strftime('%B %Y')
date_max = df['Sale_Date'].max().strftime('%B %Y')
avg_retail = df['Retail_Price_USD'].mean()
avg_resale = df['Resale_Price_USD'].mean()
median_margin = df['Profit_Margin_USD'].median()
margin_std = df['Profit_Margin_USD'].std()
pct_above_retail = df['Is_Profitable'].mean() * 100

# ── Helper: chart to HTML div ────────────────────────────────────────
def fig_to_html(fig, chart_id):
    return fig.to_html(full_html=False, include_plotlyjs=False, div_id=chart_id)

charts_html = []

def add_chart(fig, chart_id):
    charts_html.append(fig_to_html(fig, chart_id))

# ── Chart 1: Profit Margin Distribution ──────────────────────────────
fig1 = go.Figure()
fig1.add_trace(go.Histogram(
    x=df['Profit_Margin_USD'],
    nbinsx=60,
    marker_color='#1a73e8',
    opacity=0.85,
    name='Transactions'
))
fig1.add_vline(x=0, line_dash='dash', line_color='#e74c3c', line_width=2,
               annotation_text='Break-even', annotation_position='top left')
fig1.add_vline(x=avg_profit_margin, line_dash='dot', line_color='#2ecc71', line_width=2,
               annotation_text=f'Mean: ${avg_profit_margin:.2f}', annotation_position='top right')
fig1.update_layout(
    title='Distribution of Profit Margins Across All Transactions',
    xaxis_title='Profit Margin (USD)',
    yaxis_title='Number of Transactions',
    template='plotly_white',
    bargap=0.05,
    height=420,
    margin=dict(l=40, r=40, t=50, b=40)
)
add_chart(fig1, 'chart-profit-dist')

# ── Chart 2: Model Performance ───────────────────────────────────────
model_stats = df.groupby('Shoe_Model').agg(
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_profit=('Profit_Margin_USD', 'mean'),
    avg_ratio=('Resale_to_Retail', 'mean'),
    volume=('Transaction_ID', 'count'),
    avg_retail=('Retail_Price_USD', 'mean')
).sort_values('avg_profit', ascending=True)

fig2 = make_subplots(rows=1, cols=2,
                     subplot_titles=('Average Profit Margin by Model', 'Transaction Volume by Model'),
                     specs=[[{}, {}]],
                     column_widths=[0.55, 0.45],
                     horizontal_spacing=0.12)

fig2.add_trace(go.Bar(
    y=model_stats.index,
    x=model_stats['avg_profit'],
    orientation='h',
    marker_color=np.where(model_stats['avg_profit'] > 0, '#2ecc71', '#e74c3c'),
    text=[f'${v:.1f}' for v in model_stats['avg_profit']],
    textposition='outside',
    insidetextanchor='start',
    name='Avg Profit'
), row=1, col=1)

fig2.add_trace(go.Bar(
    y=model_stats.index,
    x=model_stats['volume'],
    orientation='h',
    marker_color='#1a73e8',
    text=model_stats['volume'],
    textposition='outside',
    name='Volume'
), row=1, col=2)

fig2.update_layout(
    title='Air Jordan Model Performance: Profitability & Volume',
    template='plotly_white',
    height=380,
    showlegend=False,
    margin=dict(l=40, r=80, t=50, b=40)
)
fig2.update_xaxes(title_text='Avg Profit Margin (USD)', row=1, col=1)
fig2.update_xaxes(title_text='Number of Transactions', row=1, col=2)
add_chart(fig2, 'chart-model-perf')

# ── Chart 3: Top Colorways ───────────────────────────────────────────
colorway_stats = df.groupby('Colorway').agg(
    avg_profit=('Profit_Margin_USD', 'mean'),
    avg_resale=('Resale_Price_USD', 'mean'),
    volume=('Transaction_ID', 'count'),
    avg_ratio=('Resale_to_Retail', 'mean')
).sort_values('avg_profit', ascending=True)

# Top 15 and bottom 5
top_n = 15
bottom_n = 5
top_colorways = pd.concat([colorway_stats.head(bottom_n), colorway_stats.tail(top_n)])

fig3 = go.Figure()
colors = ['#e74c3c' if v < 0 else '#2ecc71' for v in top_colorways['avg_profit']]
fig3.add_trace(go.Bar(
    y=top_colorways.index,
    x=top_colorways['avg_profit'],
    orientation='h',
    marker_color=colors,
    text=[f'${v:.1f}  (n={c})' for v, c in zip(top_colorways['avg_profit'], top_colorways['volume'])],
    textposition='outside',
    insidetextanchor='start'
))
fig3.update_layout(
    title=f'Top & Bottom Colorways by Average Profit Margin',
    xaxis_title='Average Profit Margin (USD)',
    template='plotly_white',
    height=500,
    showlegend=False,
    margin=dict(l=40, r=100, t=50, b=40)
)
add_chart(fig3, 'chart-colorways')

# ── Chart 4: Condition Impact ────────────────────────────────────────
cond_stats = df.groupby('Condition').agg(
    avg_profit=('Profit_Margin_USD', 'mean'),
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_retail=('Retail_Price_USD', 'mean'),
    avg_ratio=('Resale_to_Retail', 'mean'),
    pct_profitable=('Is_Profitable', 'mean'),
    volume=('Transaction_ID', 'count'),
    avg_days=('Days_in_Inventory', 'mean')
).reindex(['Deadstock (Brand New)', 'VNDS (Very Near Deadstock)', 'Used'])

cond_order = cond_stats.index.tolist()

fig4 = make_subplots(rows=1, cols=3,
                     subplot_titles=('Average Profit Margin by Condition',
                                     'Resale-to-Retail Ratio by Condition',
                                     '% Transactions Above Retail'),
                     column_widths=[0.35, 0.35, 0.3])

fig4.add_trace(go.Bar(
    x=cond_order,
    y=cond_stats['avg_profit'],
    marker_color=['#2ecc71', '#f39c12', '#e74c3c'],
    text=[f'${v:.2f}' for v in cond_stats['avg_profit']],
    textposition='outside',
    name='Avg Profit'
), row=1, col=1)

fig4.add_trace(go.Bar(
    x=cond_order,
    y=cond_stats['avg_ratio'],
    marker_color=['#2ecc71', '#f39c12', '#e74c3c'],
    text=[f'{v:.2f}x' for v in cond_stats['avg_ratio']],
    textposition='outside',
    name='Ratio'
), row=1, col=2)

fig4.add_trace(go.Bar(
    x=cond_order,
    y=cond_stats['pct_profitable'] * 100,
    marker_color=['#2ecc71', '#f39c12', '#e74c3c'],
    text=[f'{v*100:.1f}%' for v in cond_stats['pct_profitable']],
    textposition='outside',
    name='% Profitable'
), row=1, col=3)

fig4.update_layout(
    title='Impact of Shoe Condition on Resale Value',
    template='plotly_white',
    height=400,
    showlegend=False,
    margin=dict(l=40, r=40, t=50, b=40)
)
fig4.update_yaxes(title_text='USD', row=1, col=1)
fig4.update_yaxes(title_text='Multiplier', row=1, col=2)
fig4.update_yaxes(title_text='Percentage', row=1, col=3)
add_chart(fig4, 'chart-condition')

# ── Chart 5: Channel Performance ─────────────────────────────────────
channel_stats = df.groupby('Sales_Channel').agg(
    avg_profit=('Profit_Margin_USD', 'mean'),
    avg_resale=('Resale_Price_USD', 'mean'),
    avg_days=('Days_in_Inventory', 'mean'),
    volume=('Transaction_ID', 'count'),
    pct_profitable=('Is_Profitable', 'mean'),
    avg_ratio=('Resale_to_Retail', 'mean')
).sort_values('avg_profit', ascending=True)

fig5 = make_subplots(rows=1, cols=2,
                     subplot_titles=('Profit Margin vs. Inventory Velocity by Channel',
                                     'Channel Volume & % Profitable'),
                     specs=[[{'secondary_y': False}, {}]],
                     column_widths=[0.55, 0.45])

# Bubble chart: x=avg_days, y=avg_profit, size=volume
fig5.add_trace(go.Scatter(
    x=channel_stats['avg_days'],
    y=channel_stats['avg_profit'],
    mode='markers+text',
    marker=dict(
        size=channel_stats['volume'] / 3,
        color=channel_stats['avg_profit'],
        colorscale='RdYlGn',
        showscale=True,
        colorbar=dict(title='Avg Profit $', x=1.0),
        line=dict(width=1, color='#333')
    ),
    text=channel_stats.index,
    textposition='top center',
    textfont=dict(size=11),
    hovertemplate='<b>%{text}</b><br>Avg Profit: $%{y:.2f}<br>Avg Days: %{x:.1f}<br>Volume: %{marker.size:.0f}<extra></extra>'
), row=1, col=1)

fig5.add_trace(go.Bar(
    y=channel_stats.index,
    x=channel_stats['volume'],
    orientation='h',
    marker_color='#1a73e8',
    text=[f'{int(v)} txns' for v in channel_stats['volume']],
    textposition='outside',
    name='Volume'
), row=1, col=2)

fig5.update_layout(
    title='Sales Channel Performance: Margin, Speed & Scale',
    template='plotly_white',
    height=420,
    showlegend=False,
    margin=dict(l=40, r=40, t=50, b=40)
)
fig5.update_xaxes(title_text='Average Days in Inventory', row=1, col=1)
fig5.update_yaxes(title_text='Average Profit Margin (USD)', row=1, col=1)
fig5.update_xaxes(title_text='Number of Transactions', row=1, col=2)
add_chart(fig5, 'chart-channel')

# ── Chart 6: Channel Profitability Bar ───────────────────────────────
fig6 = go.Figure()
fig6.add_trace(go.Bar(
    y=channel_stats.index,
    x=channel_stats['avg_profit'],
    orientation='h',
    marker_color=np.where(channel_stats['avg_profit'] > 0, '#2ecc71', '#e74c3c'),
    text=[f'${v:.2f}' for v in channel_stats['avg_profit']],
    textposition='outside',
    insidetextanchor='start'
))
fig6.update_layout(
    title='Average Profit Margin by Sales Channel',
    xaxis_title='Average Profit Margin (USD)',
    template='plotly_white',
    height=320,
    showlegend=False,
    margin=dict(l=40, r=60, t=50, b=40)
)
add_chart(fig6, 'chart-channel-profit')

# ── Chart 7: Temporal Trends ─────────────────────────────────────────
monthly = df.groupby('Month').agg(
    avg_profit=('Profit_Margin_USD', 'mean'),
    avg_resale=('Resale_Price_USD', 'mean'),
    volume=('Transaction_ID', 'count'),
    avg_days=('Days_in_Inventory', 'mean'),
    avg_ratio=('Resale_to_Retail', 'mean')
).sort_index()
monthly.index = monthly.index.astype(str)

fig7 = make_subplots(rows=2, cols=2,
                     subplot_titles=('Monthly Transaction Volume',
                                     'Average Profit Margin Over Time',
                                     'Average Resale Price Over Time',
                                     'Average Days in Inventory Over Time'),
                     vertical_spacing=0.13,
                     horizontal_spacing=0.1)

fig7.add_trace(go.Scatter(
    x=monthly.index, y=monthly['volume'],
    mode='lines+markers', line=dict(color='#1a73e8', width=2),
    fill='tozeroy', fillcolor='rgba(26,115,232,0.1)',
    name='Volume'
), row=1, col=1)

fig7.add_trace(go.Scatter(
    x=monthly.index, y=monthly['avg_profit'],
    mode='lines+markers', line=dict(color='#2ecc71', width=2),
    fill='tozeroy', fillcolor='rgba(46,204,113,0.1)',
    name='Avg Profit'
), row=1, col=2)

fig7.add_trace(go.Scatter(
    x=monthly.index, y=monthly['avg_resale'],
    mode='lines+markers', line=dict(color='#f39c12', width=2),
    fill='tozeroy', fillcolor='rgba(243,156,18,0.1)',
    name='Avg Resale'
), row=2, col=1)

fig7.add_trace(go.Scatter(
    x=monthly.index, y=monthly['avg_days'],
    mode='lines+markers', line=dict(color='#9b59b6', width=2),
    fill='tozeroy', fillcolor='rgba(155,89,182,0.1)',
    name='Avg Days'
), row=2, col=2)

fig7.update_layout(
    title='Temporal Trends (2023–2026)',
    template='plotly_white',
    height=600,
    showlegend=False,
    margin=dict(l=40, r=40, t=50, b=40)
)
fig7.update_xaxes(tickangle=45, dtick=3, row=1, col=1)
fig7.update_xaxes(tickangle=45, dtick=3, row=1, col=2)
fig7.update_xaxes(tickangle=45, dtick=3, row=2, col=1)
fig7.update_xaxes(tickangle=45, dtick=3, row=2, col=2)
add_chart(fig7, 'chart-temporal')

# ── Chart 8: Yearly Summary ──────────────────────────────────────────
yearly = df.groupby('Year').agg(
    avg_profit=('Profit_Margin_USD', 'mean'),
    avg_resale=('Resale_Price_USD', 'mean'),
    volume=('Transaction_ID', 'count'),
    avg_days=('Days_in_Inventory', 'mean'),
    pct_profitable=('Is_Profitable', 'mean'),
    avg_ratio=('Resale_to_Retail', 'mean')
)

fig8 = make_subplots(rows=1, cols=3,
                     subplot_titles=('Yearly Transaction Volume',
                                     'Average Profit Margin by Year',
                                     'Avg Days in Inventory by Year'))

fig8.add_trace(go.Bar(
    x=yearly.index.astype(str),
    y=yearly['volume'],
    marker_color='#1a73e8',
    text=yearly['volume'],
    textposition='outside'
), row=1, col=1)

fig8.add_trace(go.Bar(
    x=yearly.index.astype(str),
    y=yearly['avg_profit'],
    marker_color=np.where(yearly['avg_profit'] > 0, '#2ecc71', '#e74c3c'),
    text=[f'${v:.2f}' for v in yearly['avg_profit']],
    textposition='outside'
), row=1, col=2)

fig8.add_trace(go.Bar(
    x=yearly.index.astype(str),
    y=yearly['avg_days'],
    marker_color='#9b59b6',
    text=[f'{v:.1f}' for v in yearly['avg_days']],
    textposition='outside'
), row=1, col=3)

fig8.update_layout(
    title='Year-over-Year Performance Summary',
    template='plotly_white',
    height=380,
    showlegend=False,
    margin=dict(l=40, r=40, t=50, b=40)
)
add_chart(fig8, 'chart-yearly')

# ── Chart 9: Condition × Channel Heatmap ─────────────────────────────
cond_channel = df.groupby(['Condition', 'Sales_Channel'])['Profit_Margin_USD'].mean().unstack()
cond_channel = cond_channel.reindex(['Deadstock (Brand New)', 'VNDS (Very Near Deadstock)', 'Used'])

fig9 = go.Figure(data=go.Heatmap(
    z=cond_channel.values,
    x=cond_channel.columns,
    y=cond_channel.index,
    colorscale='RdYlGn',
    text=[[f'${v:.2f}' for v in row] for row in cond_channel.values],
    texttemplate='%{text}',
    textfont=dict(size=12),
    colorbar=dict(title='Avg Profit $'),
    zmid=0
))
fig9.update_layout(
    title='Profit Margin Heatmap: Condition × Sales Channel',
    template='plotly_white',
    height=350,
    margin=dict(l=40, r=40, t=50, b=40)
)
add_chart(fig9, 'chart-heatmap')

# ── Build HTML Report ────────────────────────────────────────────────

# Gather stats for narrative
best_model = model_stats['avg_profit'].idxmax()
best_model_profit = model_stats['avg_profit'].max()
worst_model = model_stats['avg_profit'].idxmin()
worst_model_profit = model_stats['avg_profit'].min()

best_channel = channel_stats['avg_profit'].idxmax()
best_channel_profit = channel_stats['avg_profit'].max()
fastest_channel = channel_stats['avg_days'].idxmin()
fastest_days = channel_stats['avg_days'].min()
slowest_channel = channel_stats['avg_days'].idxmax()
slowest_days = channel_stats['avg_days'].max()

ds_profit = cond_stats.loc['Deadstock (Brand New)', 'avg_profit']
vnds_profit = cond_stats.loc['VNDS (Very Near Deadstock)', 'avg_profit']
used_profit = cond_stats.loc['Used', 'avg_profit']
ds_premium = cond_stats.loc['Deadstock (Brand New)', 'avg_ratio']
used_ratio = cond_stats.loc['Used', 'avg_ratio']
ds_pct = cond_stats.loc['Deadstock (Brand New)', 'pct_profitable'] * 100
used_pct = cond_stats.loc['Used', 'pct_profitable'] * 100

