    name='Avg Days'
), row=2, col=2)

fig7.update_layout(
    title='Temporal Trends (2023–2026)',
    template='plotly_white',
    height=600,
    showlegend=False,
    margin=dict(l=40, r=40, t=50, b=40)
)
fig7.update_xaxes(tickangle=45, dtick=3, row=1, col=1)
fig7.update_xaxes(tickangle=45, dtick=3, row=1, col=2)
fig7.update_xaxes(tickangle=45, dtick=3, row=2, col=1)
fig7.update_xaxes(tickangle=45, dtick=3, row=2, col=2)
add_chart(fig7, 'chart-temporal')

# ── Chart 8: Yearly Summary ──────────────────────────────────────────
yearly = df.groupby('Year').agg(
